public enum VendingState { Idle, HasMoney, Dispensing, OutOfStock }

public class Product
{
    public string Code { get; } // e.g., "A1"
    public string Name { get; }
    public decimal Price { get; }
    public int Quantity { get; set; }
}

public class VendingMachine
{
    public VendingState State { get; private set; } = VendingState.Idle;
    public decimal InsertedAmount { get; private set; }
    private readonly Dictionary<string, Product> _products = new();

    public void InsertCoin(decimal amount) => InsertedAmount += amount;

    public Product? Select(string code)
    {
        if (State != VendingState.Idle && State != VendingState.HasMoney)
            return null;
        if (!_products.TryGetValue(code, out var product) || product.Quantity <= 0)
        {
            State = VendingState.OutOfStock;
            return null;
        }
        if (InsertedAmount < product.Price)
        {
            State = VendingState.HasMoney;
            return null; // insufficient funds
        }
        State = VendingState.Dispensing;
        product.Quantity--;
        return product;
    }

    public decimal ReturnChange()
    {
        var change = InsertedAmount;
        InsertedAmount = 0;
        State = VendingState.Idle;
        return change;
    }
}
